import fs from 'node:fs/promises';
const out=process.cwd()+'/docs/qa/reversao-sprites';await fs.mkdir(out,{recursive:true});
const pages=await(await fetch('http://127.0.0.1:9222/json')).json();
const ws=new WebSocket(pages.find(p=>p.type==='page').webSocketDebuggerUrl);await new Promise(r=>ws.onopen=r);
let id=0;const pending=new Map();const errors=[];ws.onmessage=({data})=>{const m=JSON.parse(data);if(m.method==='Runtime.exceptionThrown')errors.push(m.params.exceptionDetails);if(pending.has(m.id)){const {resolve,reject}=pending.get(m.id);pending.delete(m.id);m.error?reject(Error(JSON.stringify(m.error))):resolve(m.result);}};
const send=(method,params={})=>new Promise((resolve,reject)=>{pending.set(++id,{resolve,reject});ws.send(JSON.stringify({id,method,params}));});
const ev=async(expression)=>{const r=await send('Runtime.evaluate',{expression,awaitPromise:true,returnByValue:true});if(r.exceptionDetails)throw Error(JSON.stringify(r.exceptionDetails));return r.result.value;};
try{await send('Runtime.enable');await send('Network.enable');await send('Network.setCacheDisabled',{cacheDisabled:true});
for(const [perfil,width,height,mobile]of [['desktop',960,540,false],['android',390,844,true]]){
await send('Emulation.setDeviceMetricsOverride',{width,height,deviceScaleFactor:1,mobile});await send('Page.navigate',{url:'http://127.0.0.1:3001/tests/battle-gameplay.html'});
for(let i=0;i<200;i++){if(await ev('Boolean(document.querySelector("#auto")) && document.querySelector("#status").textContent.includes("Cena da espada")'))break;await new Promise(r=>setTimeout(r,100));}
const result=await ev(`(async()=>{
const {AssetManager}=await import('/src/js/assets/AssetManager.js');const {ToyRoomPhase}=await import('/src/js/toy-room/ToyRoomPhase.js');
const {runToyRoomQA}=await import('/tests/toy-room-qa-runner.js');const {runBattleGameplay}=await import('/tests/battle-gameplay-runner.js');
const assets=new AssetManager({manifestUrl:'/assets/manifest.json'});await assets.loadManifest();assets.manifest.images=Object.fromEntries(Object.entries(assets.manifest.images).map(([k,p])=>[k,new URL(p,location.origin+"/").href]));await assets.preload();
const canvas=document.createElement('canvas');canvas.width=${width};canvas.height=${height};
const room=new ToyRoomPhase(canvas,null,null,()=>{},{assets});await room.battle.readyPromise;if(room.battle.error)throw Error(room.battle.error);
const shots={},sources=new Map();const draw=CanvasRenderingContext2D.prototype.drawImage;
CanvasRenderingContext2D.prototype.drawImage=function(image,...args){if(this.canvas===canvas&&image.src){const src=new URL(image.src).pathname;const key=src+'|'+args.slice(0,4).join(',');if(!sources.has(key))sources.set(key,{arquivo:src,recorte:args.length===8?args.slice(0,4):null});}return draw.call(this,image,...args);};
const render=room.render.bind(room);room.render=()=>{render();const s=room.battle.state;const name=s?('combate-'+s.enemy.actor+'-'+(s.transition?'transicao':s.crouching?'agachada':s.attackTime>0?'ataque':s.jump>0?'salto':'movimento')):room.player.carriedItem?'carregando':room.story.state.investigationStage;if(!shots[name])shots[name]=canvas.toDataURL().split(',')[1];};
try{room.render();const exploration=runToyRoomQA(room,{draw:true});const initialBattle=room.snapshot();
for(let i=0;i<150;i++)room.update(1);room.keysDown={ArrowUp:true};room.update(1);room.keysDown={};for(let i=0;i<10;i++)room.update(1);if(!(room.battle.state.jump>0))throw Error('Salto não iniciou.');room.render();shots.salto=canvas.toDataURL().split(',')[1];
room.restore(initialBattle);for(let i=0;i<150;i++)room.update(1);room.keysDown={ArrowDown:true};room.update(1);if(!room.battle.state.crouching)throw Error('Agachamento não iniciou.');room.render();shots.agachamento=canvas.toDataURL().split(',')[1];
room.restore(initialBattle);const battle=runBattleGameplay(room,{draw:true,restore:true});room.render();shots.vitoria=canvas.toDataURL().split(',')[1];
room.restore(initialBattle);let defeatFrames=0;while(room.battle.state.mode==='BATTLE'&&defeatFrames<10000){const delta=room.battle.state.enemy.x-room.player.x;room.keysDown=Math.abs(delta)>50?{[delta>0?'ArrowRight':'ArrowLeft']:true}:{};room.update(1);defeatFrames++;}if(room.battle.state.mode!=='DEFEAT')throw Error('Derrota não alcançada.');room.render();shots.derrota=canvas.toDataURL().split(',')[1];const additional={salto:true,agachamento:true,derrota:true,quadrosAteDerrota:defeatFrames};
return {exploration,battle,additional,recursos:[...assets.statuses],fontes:[...sources.values()],shots};}finally{CanvasRenderingContext2D.prototype.drawImage=draw;room.destroy();}
})()`);
for(const [name,data]of Object.entries(result.shots))await fs.writeFile(`${out}/${perfil}-${name}.png`,Buffer.from(data,'base64'));delete result.shots;result.excecoes=errors;
await fs.writeFile(`${out}/${perfil}.json`,JSON.stringify(result,null,2)+'\n');console.log(perfil,JSON.stringify({exploracao:result.exploration,combate:result.battle,recursosComFalha:result.recursos.filter(x=>x[1]!=='ready'),excecoes:errors.length}));
}
}finally{ws.close();}
